#!/usr/bin/env python3
"""Publish the actual rehearsal journals, exact checklist wording, and live record links."""
from datetime import datetime,timezone
import hashlib,html,json,re
from pathlib import Path
from build_books import inline,render

ROOT=Path(__file__).resolve().parents[1];AUDIT=ROOT/'audit';BASE='http://127.0.0.1:8875'
def load(p):return json.loads(p.read_text())
def href(p):return html.escape(str(p),quote=True)
def tag(status):return f'<span class="status {status}">{html.escape({"passed":"Passed","failed":"Harness attempt failed","exercised":"Exercised","reviewed":"Reviewed against evidence","human":"Presenter action","native":"Native desktop check","conditional":"Conditional guidance"}.get(status,status))}</span>'

def main():
    final=load(AUDIT/'final-state/manifest.json')
    (AUDIT/'live-sources.json').write_text((ROOT/'fixtures/public/verification.json').read_text())
    attempts=[(p,load(p)) for p in sorted((AUDIT/'attempts').glob('*/journal.json'))]
    all_steps=[];frames=[];chapter_proof={}
    for p,journal in attempts:
        for step in journal['steps']:
            directory=str(p.parent.relative_to(ROOT));step=dict(step,attempt=journal['attempt'],directory=directory)
            all_steps.append(step)
            if step['status']=='passed':
                chapter_proof.setdefault(step['chapter'],[]).append(directory+'/journal.json')
                if step.get('screenshot'):frames.append({'title':'Chapter '+step['chapter']+' · '+step['title'],'url':directory+'/'+step['screenshot'],'time':step['finished_at'],'state':'Recorded browser exercise'})
                proof=step.get('proof',{})
                for img in proof.get('screenshots',[]):frames.append({'title':step['title']+' · workplace evidence','url':directory+'/'+img,'time':step['finished_at'],'state':'Recorded workplace form'})
                for record in proof.get('outputs',[]):
                    if isinstance(record,dict) and record.get('screenshot'):frames.append({'title':step['title']+' · '+record.get('app','saved destination'),'url':directory+'/'+record['screenshot'],'time':step['finished_at'],'state':'Recorded saved destination'})
    for chapter,paths in {'00':['books/verification/result.json','audit/reader-tests.log'],'01':['audit/lifecycle/proof.json','audit/file-lessons/commands.json'],'03':['docs/IMPLEMENTATION.md','audit/final-state/manifest.json'],'07':['audit/file-lessons/commands.json'],'23':['audit/lifecycle/proof.json'],'24':['audit/lifecycle/proof.json','books/verification/result.json'],'25':['audit/final-state/manifest.json'],'26':['audit/final-state/manifest.json','books/verification/result.json']}.items():
        chapter_proof.setdefault(chapter,[]).extend(paths)
    chapter_proof.setdefault('09',[]).append('audit/file-lessons/commands.json');chapter_proof.setdefault('22',[]).append('audit/file-lessons/commands.json')
    checks=[]
    for stem,book in [('THE_WORKS','works'),('BUSINESS_PLAYBOOK','business')]:
        chapter='00';title='';order=0
        for line in (ROOT/'docs'/f'{stem}.md').read_text().splitlines():
            m=re.match(r'## (\d{2})\. (.*)',line)
            if m:chapter,title=m.groups();order=0
            if not line.startswith('- [ ] '):continue
            text=line[6:];order+=1
            id='chapter-'+chapter+'-'+hashlib.sha256(text.encode()).hexdigest()[:12]
            status='exercised';reason='The relevant browser or command sequence ran. Linked evidence shows the observed state; screenshots are from that run.'
            if book=='business' and chapter!='00':status='human';reason='Written talking material is prepared. Asking/listening/presenting to an actual owner was not performed by the automation.'
            elif re.search(r'Pass checkpoint|Book complete|Read this chain aloud|Practice the exact|Finish with a concrete|Start with “|^Explain |\. Explain |^State the demo',text):status='human';reason='The supporting facts were checked, but speaking, learning, or assessing your own readiness is a presenter action.'
            elif re.search(r'Alt\+F2|double-click|single click|press \*\*F2|Ctrl\+L|Ctrl\+Shift\+V|trust-prompt|Show in folder|Downloads list|save-as|Save As|Print / save PDF|If KDE|In Dolphin|In Kitty|Dolphin or Kitty|^Locate the board',text,re.I):status='native';reason='Equivalent files, programs, browser behavior, or outputs were exercised. The physical desktop shortcut, file chooser, trust prompt, print dialog, or Save As interaction itself is not claimed as clicked.'
            elif text.startswith(('If ','**If ','For **403**','For **409**','For **422**','For an archived','For PDF/OCR','A private Sheet')):status='conditional';reason='Conditional recovery guidance was checked against implemented behavior. The evidence distinguishes intentionally triggered failures from conditions that were not present.'
            elif re.match(r'(Understand|Read |Notice|Observe|Compare|Look |Identify|Distinguish)',text):status='reviewed';reason='Reviewed against the displayed source, saved outputs, actual application contract, or retained trace; this is not a separate external action.'
            evidence=sorted(set(chapter_proof.get(chapter,[]))) if book=='works' else ['BUSINESS_PLAYBOOK.html#chapter-'+chapter,'audit/OWNER_REHEARSAL.md']
            if book=='business' and chapter=='00':evidence=['books/verification/result.json','audit/reader-tests.log']
            checks.append({'book':book,'chapter':chapter,'chapter_title':title,'number':order,'id':id,'text':text,'status':status,'reason':reason,'evidence':evidence})
    (AUDIT/'checklist-coverage.json').write_text(json.dumps(checks,indent=2)+'\n')
    for book in ['works','business']:
        selected=[c for c in checks if c['book']==book]
        progress={'version':1,'book':book,'checks':{c['id']:c['status'] in ['exercised','reviewed'] for c in selected},'notes':{},'chapter':'chapter-00','exported_at':datetime.now(timezone.utc).isoformat()}
        (AUDIT/f'{book}-verified-progress.json').write_text(json.dumps(progress,indent=2)+'\n')
    works=[c for c in checks if c['book']=='works'];counts={k:sum(c['status']==k for c in works) for k in ['exercised','reviewed','native','human','conditional']}
    report={'generated_at':datetime.now(timezone.utc).isoformat(),'base':BASE,'browser_exercises_passed':sum(s['status']=='passed' for s in all_steps),'prior_harness_attempts_failed':sum(s['status']=='failed' for s in all_steps),'operator_checks':len(works),'business_checks':len(checks)-len(works),'operator_coverage':counts,'workplace_apps':24,'records':final['record_count'],'frames':len(frames),'findings':'audit/FINDINGS.md','schedule_enabled':final['schedule']['enabled']}
    (AUDIT/'summary.json').write_text(json.dumps(report,indent=2)+'\n')
    # Rehearsal words are visibly fictional examples, not fabricated customer interviews.
    words=['# Written presentation rehearsal','These are prepared words using the fictional businesses and the actual final saved records. No owner was interviewed and no external message was sent.','## Opening','“I connect the repeated handoffs between the tools a business uses. Here is the original input, here are the separate places that need it, and here are the saved records after one reviewed intake. I can also show an interrupted handoff and its recovery.”']
    for s in final['scenarios']:
        words+=['## '+s['name'],f'“In this fictional {s["company"]} example, the workflow saved records in '+', '.join(a['name'] for a in s['apps'])+'. Each has its own stored ID. Let’s open those records rather than relying only on a success banner.”', 'Observed results: '+ '; '.join(f'{a["name"]}: {a["count"]} saved records, selected record {a["record_id"]}, status {a["status"]}' for a in s['apps'])+'.','Ask the owner: “Where do you retype these facts today? What identifies the same job or person? Who approves changes, and what should happen when a destination cannot accept an update?”','Technical follow-up: “The local connector writes through an authenticated API, reads the result back, and compares the saved values. Your actual product still needs its own supported interface, permission, mapping, and tests.”']
    words+=['## Closing','“The next useful step is one permitted fictional or redacted example, the names of your actual systems, the account owner, and a result we can objectively verify. Which handoff is worth examining first?”','## Cost language','“This showcase has no required paid service charges on the existing computer. A real deployment has separate implementation, hosting, vendor, and support choices. Field counts are not measured labor savings, and the demo is not a production capacity benchmark.”']
    (AUDIT/'OWNER_REHEARSAL.md').write_text('\n\n'.join(words)+'\n')
    css=(ROOT/'web/audit.css').read_text()
    records=''
    for s in final['scenarios']:
        records+=f'<article class="business-card"><div class="eyebrow">{html.escape(s["company"])}</div><h3>{html.escape(s["name"])}</h3><a class="result-shot" href="audit/final-state/{s["id"]}-results.png" target="_blank"><img loading="lazy" src="audit/final-state/{s["id"]}-results.png" alt="Verified final {html.escape(s["name"])} results"></a><p><a href="{BASE}/#scenario/{s["id"]}/results" target="_blank">Open working workflow ↗</a></p><ul>'+''.join(f'<li><a href="{BASE}{href(a["url"])}" target="_blank">{html.escape(a["name"])}</a><span>{a["count"]} saved · {html.escape(a["status"])}</span><small><a href="audit/final-state/{a["id"]}.pdf" target="_blank">PDF</a> · <a href="audit/final-state/{a["id"]}.csv" download>CSV</a> · <a href="audit/final-state/{a["id"]}.png" target="_blank">Screenshot</a></small></li>' for a in s['apps'])+'</ul></article>'
    journal=''
    for s in all_steps:
        proof=s.get('proof',{});extras=proof.get('screenshots',[])+[o['screenshot'] for o in proof.get('outputs',[]) if isinstance(o,dict) and o.get('screenshot')]
        journal+=f'<details class="exercise searchable" data-status="{s["status"]}"><summary><span class="exercise-id">CH {s["chapter"]} / {s["id"]}</span><strong>{html.escape(s["title"])}</strong>{tag(s["status"])}</summary><div class="exercise-body"><p class="muted">{html.escape(s["finished_at"])} · {html.escape(s["attempt"])}</p><p><a href="{s["directory"]}/journal.json" target="_blank">Complete journal and recorded values ↗</a> · <a href="{s["directory"]}/browser-trace.zip" download>Browser trace ZIP</a></p>'
        if s.get('screenshot'):journal+=f'<a href="{s["directory"]}/{s["screenshot"]}" target="_blank"><img loading="lazy" src="{s["directory"]}/{s["screenshot"]}" alt="{html.escape(s["title"])}"></a>'
        if extras:journal+='<div class="extra-links">'+''.join(f'<a href="{s["directory"]}/{href(img)}" target="_blank">Workplace capture {i+1} ↗</a>' for i,img in enumerate(extras))+'</div>'
        data=s.get('error') or json.dumps(proof,indent=2,ensure_ascii=False)
        journal+='<pre>'+html.escape(data[:14000])+('\n[Preview shortened. Open the complete journal above.]' if len(data)>14000 else '')+'</pre></div></details>'
    check_html=''
    for c in checks:
        check_html+=f'<details class="check-item searchable" data-status="{c["status"]}" data-book="{c["book"]}"><summary><span class="exercise-id">{c["book"].upper()} {c["chapter"]}.{c["number"]:02d}</span>{tag(c["status"])}<span class="check-wording">{inline(c["text"])}</span></summary><div class="check-detail"><p>{html.escape(c["reason"])}</p><p>Chapter: {html.escape(c["chapter_title"])}</p><div class="extra-links">'+''.join(f'<a href="{href(p)}" target="_blank">{html.escape(p)}</a>' for p in c['evidence'])+'</div></div></details>'
    findings=render((AUDIT/'FINDINGS.md').read_text(),'findings')[0]
    stats=f'<div class="stats"><article><strong>{report["browser_exercises_passed"]}</strong><span>Passed browser exercises</span></article><article><strong>24</strong><span>Populated workplace apps</span></article><article><strong>{final["record_count"]}</strong><span>Saved destination records</span></article><article><strong>{len(checks)}</strong><span>Checklist items accounted for</span></article></div>'
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rehearsal findings · free_intro_1</title><style>{css}</style><script src="audit/report-data.js" defer></script><script src="web/audit.js" defer></script></head><body><header class="site-header"><a class="brand" href="AUDIT.html">↗ relayworks <small>FREE_INTRO_1 · REHEARSAL</small></a><a class="button" href="{BASE}/" target="_blank">Open populated demo ↗</a><a href="START_HERE.html">The two books</a></header><main><div class="eyebrow">ACTUAL ACTIONS. RECORDED RESULTS. VISIBLE LIMITS.</div><h1>The rehearsal,<br>step by step.</h1><p class="lead">I ran the documented software paths in this separate copy, fixed the problems found, and left all eight businesses populated. You can inspect the clicks, the words in each checklist, and the records that actually landed.</p>{stats}<div class="notice"><strong>This is evidence, not a promise of zero possible bugs.</strong> Native desktop prompts, spoken practice, and real business-owner conversations remain explicitly marked. The timer is off. Screenshots show recorded actions; the live-app links open the saved working copy.</div><nav class="report-tabs" aria-label="Report views"><a href="#results" data-view="results">Populated apps</a><a href="#replay" data-view="replay">Watch the steps</a><a href="#journal" data-view="journal">Action journal</a><a href="#checklist" data-view="checklist">Every checklist item</a><a href="#findings" data-view="findings">Findings & limits</a><a href="#files" data-view="files">Files & test results</a></nav>
<section class="view" id="results"><h2>Open any business. Its records are there.</h2><p class="muted">Final arrangement created {html.escape(final['finished_at'])}. Each workplace has its own database. These are fictional businesses; Google and OpenF1 data retain their actual source timestamps.</p><div class="business-grid">{records}</div></section>
<section class="view" id="replay" hidden><h2>Replay the recorded work.</h2><p>This is a slideshow of actual browser captures, not a live execution. Use the journal for exact saved values and request traces.</p><div class="replay-toolbar"><button id="previous-frame">Previous</button><button class="primary" id="play-frames">Play screenshots</button><button id="next-frame">Next</button><label>Step <input type="range" id="frame-slider" min="0" max="{len(frames)-1}" value="0"></label><span id="frame-counter"></span></div><h3 id="frame-title"></h3><p id="frame-meta" class="muted"></p><a id="frame-link" target="_blank"><img id="frame-image" alt="Recorded rehearsal step"></a></section>
<section class="view" id="journal" hidden><h2>What ran, and what happened.</h2><p>The initial selector failure is retained for honesty. It was corrected; the subsequent full browser rehearsal passed. The later document retest records the PDF/OCR corrections.</p><label class="search">Search actions <input id="action-search" type="search" placeholder="invoice, manual, Google, OCR…"></label>{journal}</section>
<section class="view" id="checklist" hidden><h2>The exact checklist words, accounted for.</h2><p>A browser exercise can cover several related checklist actions. Each item links its supporting evidence. “Exercised” describes the relevant automated sequence; it does not claim an unobserved physical desktop gesture or a conversation with a business owner.</p><div class="check-controls"><label>Book <select id="book-filter"><option value="works">The Works</option><option value="business">Business Owner Playbook</option><option value="all">Both books</option></select></label><label>Status <select id="status-filter"><option value="all">All statuses</option><option value="exercised">Exercised</option><option value="reviewed">Reviewed against evidence</option><option value="native">Native desktop check</option><option value="human">Presenter action</option><option value="conditional">Conditional guidance</option></select></label><label>Search <input id="check-search" type="search" placeholder="Exact words or chapter topic"></label><span id="check-count"></span></div><p class="coverage">Operator coverage: {counts['exercised']} exercised · {counts['reviewed']} reviewed · {counts['native']} native-desktop items · {counts['human']} presenter actions · {counts['conditional']} conditional guidance.</p><p><a href="audit/works-verified-progress.json" download>Download observed operator progress</a> · <a href="audit/checklist-coverage.json" download>Download every item and its evidence</a>. Import progress in the matching book; native/presenter items remain unticked.</p>{check_html}</section>
<section class="view findings" id="findings" hidden>{findings}</section>
<section class="view" id="files" hidden><h2>The evidence stays in this folder.</h2><div class="file-grid"><article><h3>Findings and rehearsal words</h3><p><a href="audit/FINDINGS.md">Findings report</a></p><p><a href="audit/OWNER_REHEARSAL.md">Written presentation rehearsal</a></p><p><a href="audit/summary.json">Machine-readable summary</a></p></article><article><h3>Executed checks</h3><p><a href="audit/backend-tests-after-fixes.log">20 backend/regression tests</a></p><p><a href="audit/reader-tests-after-report.log">File/web/mobile book-reader checks</a></p><p><a href="audit/report-verification/result.json">Report links, replay controls, exact checklist IDs, and final records</a></p><p><a href="audit/original/comparison.json">Original workspace preservation check</a></p><p><a href="audit/capture-run.log">134-capture browser run</a></p><p><a href="audit/source-review-fixes/result.json">Corrected source-review browser checks</a></p></article><article><h3>Files, maps, and recovery</h3><p><a href="audit/file-lessons/commands.json">LibreOffice, PDF/OCR, and 10 Archi exports</a></p><p><a href="audit/lifecycle/proof.json">Start/stop/backup/restore proof</a></p><p><a href="audit/final-state/manifest.json">All final records and source references</a></p><p><a href="audit/live-sources.json">Fresh public-source verification</a></p></article></div><p>Browser traces can be opened with <code>npx playwright show-trace audit/attempts/ATTEMPT/browser-trace.zip</code> from this copy's folder, replacing ATTEMPT with the timestamped directory. The screenshot slideshow works without that development tool.</p><p>Start this copy with <code>python3 scripts/launch.py</code> from <code>{ROOT}</code>. Open <code>{BASE}/AUDIT.html</code>. The original workspace remains on 8765.</p></section><footer>Built {report['generated_at']} · $0 required paid services · Fictional business records · Real local API transfers</footer></main></body></html>'''
    (ROOT/'AUDIT.html').write_text(page)
    (AUDIT/'report-data.js').write_text('window.REHEARSAL_FRAMES = '+json.dumps(frames,ensure_ascii=False).replace('<','\\u003c')+';\n')
    print(json.dumps(report,indent=2))

if __name__=='__main__':main()
